--
-- Table structure for table `heritagesites`
--

CREATE TABLE `heritagesites` (
  `Id` int(11) NOT NULL,
  `RegionId` int(11) NOT NULL,
  `Name` varchar(100) NOT NULL,
  `Name_ar` varchar(1000) NOT NULL,
  `Description` text DEFAULT NULL,
  `Description_ar` varchar(10000) NOT NULL,
  `Image` varchar(255) DEFAULT NULL,
  `display` varchar(10) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `heritagesites`
--

INSERT INTO `heritagesites` (`Id`, `RegionId`, `Name`, `Name_ar`, `Description`, `Description_ar`, `Image`, `display`) VALUES
(1, 1, 'Shubra Palace', 'قصر شُبرا', 'One of the most famous landmarks in Taif, Saudi Arabia, Shubra Palace is known for its stunning architecture and historical significance. Built in 1905, the palace served as a royal residence and then the headquarters of the Ministry of Defense. Today, it stands as a museum showcasing the rich heritage of the region. The building’s design is a masterpiece of Hijazi architecture, blending Ottoman and Islamic styles with intricate lattices, tall windows, and beautifully carved wooden panels. The palace’s interior features marble staircases, high ceilings, and elegant decorations that reflect the ingenuity of the era. Visitors can explore the historical artifacts and marvel at its timeless beauty, making Shubra Palace a must-see destination for anyone traveling to Taif.', 'يعد قصر شبرا أحد أشهر المعالم في الطائف بالمملكة العربية السعودية، وهو معروف بهندسته المعمارية المذهلة وأهميته التاريخية. تم بناء القصر في عام 1905، وكان بمثابة مقر إقامة ملكي ثم مقر لوزارة الدفاع. واليوم، يقف كمتحف يعرض التراث الغني للمنطقة. يعد تصميم المبنى تحفة من تحف العمارة الحجازية، حيث يمزج بين الأنماط العثمانية والإسلامية مع الشبكات المعقدة والنوافذ الطويلة والألواح الخشبية المنحوتة بشكل جميل. يتميز الجزء الداخلي من القصر بسلالم رخامية وأسقف عالية وزخارف أنيقة تعكس براعة العصر. يمكن للزوار استكشاف القطع الأثرية التاريخية والتعجب من جمالها الخالد، مما يجعل قصر شبرا وجهة لا بد من زيارتها لأي شخص يسافر إلى الطائف.', 'Shubra.jpg', ''),
(2, 2, 'Al-Rahma Mosque', 'مسجد الرحمة', 'Al-Rahma Mosque, known as the “Floating Mosque,” is a captivating landmark on the Red Sea shore in Jeddah. It features a unique design that appears to float on water, with a stunning dome and windows that create a serene atmosphere. It’s an ideal spot for prayer, reflection, and photography, especially during sunrise and sunset. Don’t miss the chance to visit and enjoy the beauty of nature and architectural brilliance.', 'مسجد الرحمة المعروف باسم \"المسجد العائم\" هو معلم ساحر على شاطئ البحر الأحمر في جدة، يتميز بتصميم فريد يبدو وكأنه يطفو على الماء، مع قبة مذهلة ونوافذ تخلق جوًا هادئًا، وهو مكان مثالي للصلاة والتأمل والتصوير الفوتوغرافي، خاصة أثناء شروق الشمس وغروبها، لا تفوت فرصة زيارته والاستمتاع بجمال الطبيعة والروعة المعمارية.', 'ar-rahma_mosque.jpg', ''),
(3, 3, 'Railway ', 'السكة الحديدية', 'The railway in Medina is part of a rich history, with the Hejaz Railway station once connecting the city to Mecca and the Levant. Today, the station has been renovated and transformed into a tourist landmark that reflects the region’s past in transportation and trade.', 'تشكل السكك الحديدية في المدينة المنورة جزءًا من تاريخ غني، حيث كانت محطة سكة حديد الحجاز تربط المدينة بمكة المكرمة والشام. واليوم، تم تجديد المحطة وتحويلها إلى معلم سياحي يعكس ماضي المنطقة في النقل والتجارة.', 'Railway.jpg', ''),
(4, 8, 'Dadan', 'دادان', 'Dadan in AlUla tells the story of a great civilization that thrived in the heart of the desert. Its well-preserved ruins showcase the architectural artistry and precision of the Dadanite and Lihyanite Kingdoms. Among the rock carvings and stunning statues, you can feel the essence of history and the grandeur of the past. Visiting Dadan is not just an exploration but a journey into an ancient civilization that has inspired generations.', 'تروي دادان في العلا قصة حضارة عظيمة ازدهرت في قلب الصحراء. وتُظهِر آثارها المحفوظة جيدًا براعة العمارة ودقة المملكتين الدادانية واللحيانية. ومن بين المنحوتات الصخرية والتماثيل المذهلة، يمكنك أن تشعر بجوهر التاريخ وعظمة الماضي. إن زيارة دادان ليست مجرد استكشاف، بل هي رحلة إلى حضارة قديمة ألهمت أجيالاً.', 'AL1.jpg', ''),
(5, 8, 'AlUla Old Town', 'بلدة العلا القديمة', 'AlUla Old Town, the heart of civilizations and the cradle of history, takes you on a magical journey through time. Its narrow streets and mud-brick houses tell the stories of ancestors, filled with authenticity and warmth. In AlUla Old Town, you’ll feel as if you’re experiencing something extraordinary, blending the charm of the past with the beauty of heritage. It’s a perfect destination for cultural adventure lovers and those seeking simple, unforgettable experiences.', 'تأخذك بلدة العلا القديمة، قلب الحضارات ومهد التاريخ، في رحلة سحرية عبر الزمن. تروي شوارعها الضيقة ومنازلها المبنية من الطوب اللبن قصص الأجداد، المفعمة بالأصالة والدفء. في بلدة العلا القديمة، ستشعر وكأنك تعيش تجربة غير عادية، تمزج سحر الماضي بجمال التراث. إنها وجهة مثالية لمحبي المغامرات الثقافية والباحثين عن تجارب بسيطة لا تُنسى.', 'AL2.jpg', ''),
(6, 8, 'Madain Saleh', 'مدائن صالح', 'Madain Saleh, a jewel of history in Saudi Arabia, captivates visitors with its natural beauty and historical splendor. It features Nabatean ruins carved into the rocks, carrying stories that date back thousands of years. Here, visitors can enjoy a unique experience blending ancient architectural art with the enchanting desert landscape. Visiting Madain Saleh is not just a tourist trip; it is a journey through time to a magnificent civilization worth exploring.', 'مدائن صالح، جوهرة التاريخ في المملكة العربية السعودية، تأسر الزوار بجمالها الطبيعي وروعتها التاريخية، حيث تضم آثاراً نبطية محفورة في الصخور تحمل قصصاً تعود إلى آلاف السنين. هنا، يمكن للزائر الاستمتاع بتجربة فريدة تمزج بين الفن المعماري القديم والمناظر الطبيعية الصحراوية الساحرة. زيارة مدائن صالح ليست مجرد رحلة سياحية؛ بل هي رحلة عبر الزمن إلى حضارة رائعة تستحق الاستكشاف.', 'al3.jpg', ''),
(7, 8, 'Elephant Rock ', 'صخرة الفيل', 'Elephant Rock in AlUla is a natural wonder that showcases the beauty of geography and the marvel of formation. With its towering height and unique elephant-like shape, it amazes visitors and offers the perfect opportunity to capture stunning photos amidst the breathtaking desert landscape. When visiting, you’ll feel as though you’re standing before an artwork crafted by time, where the beauty of the desert and intricate details come together. It’s an ideal destination for those seeking relaxation and the exploration of nature’s wonders.', 'تعد صخرة الفيل في العلا من عجائب الطبيعة التي تستعرض جمال الجغرافيا وروعة التكوين، حيث تبهر الزائرين بارتفاعها الشاهق وشكلها الفريد الذي يشبه شكل الفيل، وتوفر فرصة مثالية لالتقاط صور مذهلة وسط المناظر الطبيعية الصحراوية الخلابة. وعند زيارتها، ستشعر وكأنك تقف أمام عمل فني صنعه الزمن، حيث يجتمع جمال الصحراء مع التفاصيل الدقيقة. إنها وجهة مثالية للباحثين عن الاسترخاء واستكشاف عجائب الطبيعة.', 'AL4.jpg', ''),
(8, 8, 'Al-‘Akma Mountain', 'جبل عكمة', 'Al-‘Akma Mountain in AlUla is considered one of the most prominent archaeological landmarks that reflect the rich history and culture of Saudi Arabia. Known as the \"Open Library,\" it houses over 500 inscriptions and carvings dating back to ancient civilizations such as the Lihyanite and Dadanite.\r\n\r\nThis mountain does not only tell the stories of AlUla\'s glorious past but also showcases the cultural and commercial exchanges between ancient civilizations. The inscriptions carved into its rocks vary between religious texts, laws, and poetic verses, highlighting the intellectual and cultural depth of those times.\r\n\r\nVisiting Al-‘Akma Mountain offers visitors a unique sense of reflection on history and nature together, where the beauty of the inscriptions blends with its geographical magnificence. It stands as a testament to the creativity and wisdom of ancient generations, symbolizing AlUla’s legacy as a crossroads of cultures throughout history.\r\n', 'يعد جبل العكمة في العلا من أبرز المعالم الأثرية التي تعكس التاريخ والثقافة الغنية للمملكة العربية السعودية، ويُعرف باسم \"المكتبة المفتوحة\"، ويضم أكثر من 500 نقش ومنحوتة تعود إلى حضارات قديمة مثل اللحيانيين والدادانيين. لا يروي هذا الجبل قصص الماضي المجيد للعلا فحسب، بل يعرض أيضًا التبادلات الثقافية والتجارية بين الحضارات القديمة. تتنوع النقوش المنحوتة على صخوره بين النصوص الدينية والقوانين والأبيات الشعرية، مما يبرز العمق الفكري والثقافي لتلك الأوقات. تمنح زيارة جبل العكمة الزائر شعورًا فريدًا بالتأمل في التاريخ والطبيعة معًا، حيث يمتزج جمال النقوش بروعته الجغرافية، ويقف شاهدًا على إبداع وحكمة الأجيال القديمة، ويرمز إلى إرث العلا كملتقى للثقافات عبر التاريخ.', 'jabaI.jpg', ''),
(9, 2, ' Nasif House Museum', 'متحف بيت نصيف', 'The Nasif House Museum is one of the prominent cultural landmarks in the city of Jeddah, Saudi Arabia. It is characterized by the beauty of traditional architecture, serving as a stunning example of old Hijazi design. Built in the 19th century, the museum was originally the residence of the Nasif family, one of the notable families in Jeddah. After its restoration, it became a museum that narrates the history of the city.\r\n\r\nThe museum houses a diverse collection of historical artifacts, including household tools, traditional clothing, and ancient documents that reflect the life of the community during that era. Its unique design features an inner courtyard, intricately decorated windows, and stone walls, showcasing traditional architectural styles.\r\n\r\nThe museum hosts a variety of cultural events, such as exhibitions and workshops, making it an important center for culture and the arts. It also offers visitors a rich educational experience, allowing them to learn about Jeddah\'s history and cultural heritage. The Nasif House Museum is an ideal destination for those looking to explore the rich history and culture of the region.', 'متحف بيت نصيف التاريخي هو واحد من أبرز المعالم الثقافية في مدينة جدة بالمملكة العربية السعودية. يتميز بجمال العمارة التقليدية، حيث يُعتبر مثالًا رائعًا للعمارة الحجازية القديمة. بُني المتحف في القرن التاسع عشر وكان منزلًا لعائلة نصيف، إحدى العائلات البارزة في جدة. بعد ترميمه، أصبح متحفًا يروي تاريخ المدينة.  يضم المتحف مجموعة متنوعة من المقتنيات التاريخية، بما في ذلك الأدوات المنزلية، الملابس التقليدية، والمستندات القديمة التي تعكس حياة المجتمع في تلك الفترة. يتميز بتصميمه الفريد الذي يحتوي على فناء داخلي، ونوافذ مزخرفة، وجدران من الحجر، مما يعكس الطراز المعماري التقليدي.  يستضيف المتحف فعاليات ثقافية متنوعة، مثل المعارض وورش العمل، مما يجعله مركزًا مهمًا للثقافة والفنون. كما يوفر للزوار تجربة تعليمية غنية، حيث يمكنهم التعرف على تاريخ جدة وتراثها الثقافي. يُعتبر متحف بيت نصيف التاريخي وجهة مثالية للزوار الذين يرغبون في استكشاف التاريخ والثقافة الغنية للمنطقة.', 'nassif hous.jpg', ''),
(10, 2, 'Historic Jeddah', 'جدة التاريخية', 'Historic Jeddah, also known as \"Al-Balad,\" is the cultural and historical heart of the city. This area is one of the most important heritage sites in Saudi Arabia, combining rich history with traditional architecture.\r\n\r\nAs you stroll through the streets of historic Jeddah, you will discover a collection of ancient houses with unique architectural styles that reflect the various cultural influences that have shaped the city over the centuries. These houses are characterized by beautiful decorations and colorful windows, creating a charming atmosphere.\r\n\r\nHistoric Jeddah is home to several traditional markets, such as Souq Al-Alawi and Souq Al-Badou, where you can find handicrafts and local products. Additionally, the area features a number of ancient mosques, like Al-Shafi\'i Mosque, which is one of the city\'s prominent religious landmarks.\r\n\r\nHistoric Jeddah also serves as a center for cultural events and festivals, hosting numerous activities that celebrate heritage and the arts. Visiting historic Jeddah is not just a sightseeing tour; it is a rich experience that enhances your understanding of Saudi culture and history.', 'جدة التاريخية، المعروفة أيضًا باسم \"البلد\"، هي قلب مدينة جدة الثقافي والتاريخي. تُعتبر هذه المنطقة واحدة من أهم المواقع التراثية في المملكة العربية السعودية، حيث تجمع بين التاريخ العريق والمعمار التقليدي.   عندما تتجول في شوارع جدة التاريخية، ستكتشف مجموعة من البيوت القديمة ذات الطراز المعماري الفريد، والتي تعكس التأثيرات الثقافية المختلفة التي مرت بها المدينة عبر العصور. تتميز هذه البيوت بالزخارف الجميلة والنوافذ الملونة، مما يضفي جوًا ساحرًا على المنطقة.  تحتضن جدة التاريخية العديد من الأسواق التقليدية، مثل سوق العلوي وسوق البدو، حيث يمكنك العثور على الحرف اليدوية والمنتجات المحلية. بالإضافة إلى ذلك، تحتوي المنطقة على عدد من المساجد القديمة، مثل مسجد الشافعي، الذي يُعتبر من أبرز المعالم الدينية في المدينة.  تُعد جدة التاريخية أيضًا مركزًا للفعاليات الثقافية والمهرجانات، حيث يتم تنظيم العديد من الفعاليات التي تحتفي بالتراث والفنون. إن زيارة جدة التاريخية ليست مجرد جولة سياحية، بل هي تجربة غنية تُعزز من فهمك للثقافة والتاريخ السعودي.', 'Historic Jeddah.jpg', '1'),
(11, 2, 'City Al-Taibat of Knowledge  Museum', 'متحف مدينة الطيبات العالمية للعلوم والمعرفة', 'The City of Knowledge and Goodness Museum is a captivating destination that opens the doors to a world of knowledge and discovery in the heart of Jeddah. This museum is one of the city\'s premier cultural landmarks, blending history and heritage with the latest advancements in science.\r\n\r\nWhen you visit the museum, you\'ll be surrounded by stunning architectural design that embodies the beauty of Saudi culture. The exhibits are diverse, allowing you to explore the secrets of space, discover the wonders of nature, and dive into the realms of technology and the arts. Every corner of the museum offers an interactive experience that takes you on an exciting educational journey.\r\n\r\nDon’t miss the chance to participate in the innovative workshops and events organized by the museum, where you can engage with science in a fun and exciting way. The City of Knowledge and Goodness Museum is the perfect place for families and students, combining learning and entertainment in an unforgettable experience.\r\n\r\nA visit to this museum is not just a tour; it’s a rich adventure that enhances your understanding of science and culture. Embark on an unparalleled journey at the City of Knowledge, and enjoy a unique educational experience that will stay with you for a long time!', 'متحف مدينة الطيبات العالمية للعلوم والمعرفة هو وجهة ساحرة تفتح أمامك أبواب عالم من المعرفة والاكتشاف في قلب جدة. يُعد هذا المتحف من أبرز المعالم الثقافية في المدينة، حيث يجمع بين التاريخ والتراث مع أحدث ما توصل إليه العلم.  عندما تزور المتحف، ستجد نفسك محاطًا بتصميم معماري رائع يجسد جمال الثقافة السعودية. تتنوع المعروضات في المتحف، حيث يمكنك استكشاف أسرار الفضاء، والتعرف على عجائب الطبيعة، والغوص في عالم التكنولوجيا والفنون. كل زاوية في المتحف تقدم تجربة تفاعلية تأخذك في رحلة تعليمية مثيرة.  لا تفوت الفرصة للمشاركة في ورش العمل والفعاليات المبتكرة التي يُنظمها المتحف، حيث يمكنك التفاعل مع العلوم بطريقة ممتعة ومشوقة. إن متحف مدينة الطيبات هو المكان المثالي للعائلات والطلاب، حيث يجمع بين التعلم والترفيه في تجربة لا تُنسى.  زيارة هذا المتحف ليست مجرد جولة، بل هي مغامرة غنية تعزز من فهمك للعلوم والثقافة. انطلق في رحلة لا مثيل لها في مدينة الطيبات، واستمتع بتجربة تعليمية فريدة ستبقى في ذاكرتك لفترة طويلة!', 'City of Knowledge and Goodness Museum.jpg', ''),
(12, 2, 'TeamLab Museum', 'متحف تيم لاب', 'The \"TeamLab\" Museum is a unique experience that blends art and technology in the heart of Jeddah. This museum is one of the most prominent cultural landmarks, offering a new way to interact with art through virtual and augmented reality technologies.\r\n\r\nUpon entering the museum, you\'ll be captivated by interactive art displays that take you on an exciting journey through colors and shapes. \"TeamLab\" allows you to explore digital worlds in a stunning way, where you can immerse yourself in artistic creations and interact with them, making every visit a one-of-a-kind experience.\r\n\r\nThe museum is not just a place to view art; it is a space for inspiration and creativity, where you can participate in workshops and interactive events that enhance your understanding of art and technology.\r\n\r\nVisiting the \"TeamLab\" Museum is an ideal opportunity for families and friends to enjoy a time filled with inspiration and interaction. Get ready for an exceptional experience that combines imagination and innovation in the world of modern art.', 'متحف تيم لاب هو تجربة فريدة تجمع بين الفن والتكنولوجيا في قلب جدة. يُعتبر هذا المتحف من أبرز المعالم الثقافية التي تقدم طريقة جديدة للتفاعل مع الفن من خلال تقنيات الواقع الافتراضي والافتراضي المعزز.  عند دخولك المتحف، ستستمتع بعروض فنية تفاعلية تأخذك في رحلة مشوقة عبر الألوان والأشكال. يتيح لك \"تيم لاب\" استكشاف العوالم الرقمية بطريقة مدهشة، حيث يمكنك الاندماج في اللوحات الفنية والتفاعل معها، مما يجعل كل زيارة تجربة فريدة لا تُنسى.  المتحف ليس مجرد مكان لمشاهدة الفن، بل هو مساحة للتحفيز والإبداع، حيث يمكنك المشاركة في ورش عمل وفعاليات تفاعلية تعزز من فهمك للفن والتكنولوجيا.   تعتبر زيارة متحف \"تيم لاب\" فرصة مثالية للعائلات والأصدقاء للاستمتاع بوقت مليء بالإلهام والتفاعل. استعد لتجربة استثنائية تجمع بين الخيال والابتكار في عالم الفن الحديث.', 'TeamLab.png', ''),
(13, 2, 'Abdul Raouf Khalil Museum ', 'متجف عبد الرؤوف خليل', 'Enjoy a Visit to the Abdul Raouf Khalil Museum in Jeddah: A Cultural Treasure Awaits You!\n\nAre you looking for a unique cultural experience in Jeddah? Don\'t miss the chance to visit the **Abdul Raouf Khalil Museum**, where you\'ll embark on a journey through time to explore the rich Saudi heritage.\n\nAs you step into this amazing museum, you\'ll find yourself surrounded by a stunning collection of artistic and historical pieces that reflect the beauty and grandeur of Saudi culture. From exquisite artworks to historical artifacts, each corner of the museum tells a unique story.\n\nDelight in the interactive activities and workshops offered by the museum, where you can personally experience traditional arts. You\'ll have the chance to connect with history and learn about local arts in a fun and innovative way.\n\nWhether you\'re with family or friends, the **Abdul Raouf Khalil Museum** is the perfect destination for visitors of all ages. Immerse yourself in culture and art, and discover unforgettable cultural treasures. Embark on this cultural adventure and don’t miss the opportunity to explore the beauty of Jeddah!', 'استمتع بزيارة متحف عبد الرؤوف خليل في جدة: كنز ثقافي في انتظارك! هل تبحث عن تجربة ثقافية فريدة في جدة؟ لا تفوت فرصة زيارة **متحف عبد الرؤوف خليل**، حيث ستنطلق في رحلة عبر الزمن لاستكشاف التراث السعودي الغني. عندما تخطو إلى هذا المتحف المذهل، ستجد نفسك محاطًا بمجموعة مذهلة من القطع الفنية والتاريخية التي تعكس جمال وعظمة الثقافة السعودية. من الأعمال الفنية الرائعة إلى التحف التاريخية، يروي كل ركن من أركان المتحف قصة فريدة من نوعها. استمتع بالأنشطة التفاعلية وورش العمل التي يقدمها المتحف، حيث يمكنك تجربة الفنون التقليدية شخصيًا. ستتاح لك الفرصة للتواصل مع التاريخ والتعرف على الفنون المحلية بطريقة ممتعة ومبتكرة. سواء كنت مع العائلة أو الأصدقاء، فإن **متحف عبد الرؤوف خليل** هو الوجهة المثالية للزوار من جميع الأعمار. انغمس في الثقافة والفن واكتشف كنوزًا ثقافية لا تُنسى. انطلق في هذه المغامرة الثقافية ولا تفوت فرصة استكشاف جمال جدة!', 'Abdul Raouf Khalil Museum in Jeddah.jpg', ''),
(16, 8, 'Ithlib Mountain', 'جبل إثلب', 'Ithlib Mountain - The Hidden Gem of AlUla\r\n\r\nIthlib Mountain is one of the most breathtaking natural and historical landmarks located to the east of AlUla, Saudi Arabia. This stunning mountain is characterized by its unique rock formations, which appear as if they were masterfully sculpted by nature itself. Its magical allure attracts adventurers, history enthusiasts, and nature lovers from around the world.', 'جبل إثلب - جوهرة العلا الخفية\r\n\r\nيعتبر جبل إثلب أحد المعالم الطبيعية والتاريخية الخلابة الواقعة شرقي العلا بالمملكة العربية السعودية. يتميز هذا الجبل المذهل بتكويناته الصخرية الفريدة، والتي تبدو وكأنها نحتتها الطبيعة ببراعة. يجذب جاذبيته الساحرة المغامرين وعشاق التاريخ وعشاق الطبيعة من جميع أنحاء العالم.', 'athlp.jpg', ''),
(18, 3, 'Quba', 'قباء', 'Imagine yourself walking through the serene streets of Medina, surrounded by the essence of history and the spirituality of the place. Suddenly, the Quba Mosque comes into view, the first house of worship built in Islam, radiating simplicity and majesty. Here, where the Prophet Muhammad ﷺ and his noble companions laid the foundation, your journey through time begins, taking you back to the earliest days of the message.\r\n\r\nThe Quba Mosque is not just a place for prayer; it’s a gateway to a history rich with greatness and faith. In every corner of its walls, you feel as though you can hear the stories of the early believers, moments filled with faith and determination to establish this blessed landmark. When you step inside, an indescribable sense of peace washes over you, as if the soul of the place gently embraces you.\r\n\r\nThe experience isn’t confined to the mosque itself. The surroundings are vibrant yet tranquil. Visitors from all corners of the world come together, their smiles meeting and their prayers resonating in a unity that reflects the beauty of Islam. If you’re a photography enthusiast, sunrise and sunset are magical moments when the mosque transforms into a luminous masterpiece, inspiring awe and reflection.\r\n\r\nAfter your visit to the mosque, don’t forget to explore the area. You’ll find traditional shops offering delicious local dishes, and the authentic Medina experience awaits you. Here, where the past meets the present, the visit becomes more than just a trip—it’s a timeless memory infused with a unique spirituality.', 'تخيل نفسك تسير في طرقات المدينة المنورة، يحيط بك عبق التاريخ وروحانية المكان.  فجأة، يلوح أمامك مسجد قباء، أول بيت من بيوت الله أُسس في الإسلام، بكل بساطته وهيبته.  هنا، حيث وضع النبي محمد ﷺ وأصحابه الكرام حجر الأساس، تبدأ رحلتك عبر الزمن إلى أيام البعثة الأولى.\r\n\r\nمسجد قباء ليس مجرد مكان للصلاة، بل هو نافذة على تاريخ ينبض بالعظمة والإيمان. في كل زاوية من زواياه، تشعر وكأنك تستمع إلى حكايات الأوائل، إلى لحظات اجتمع فيها الإيمان والعمل لبناء هذا الصرح المبارك. حينما تدخل إليه، ستشعر براحة لا توصف، وكأن روح المكان تحتضنك برفق.\r\n\r\nالتجربة لا تقتصر على الداخل فقط. المشهد من حول المسجد مفعم بالحياة والسكينة معًا. الزوار يأتون من كل بقاع العالم، تتلاقى ابتساماتهم وتتشابه دعواتهم، في وحدة تعكس جمال الإسلام. وإذا كنت من عشاق التصوير، فإن لحظتي الشروق والغروب تجعل المسجد يبدو كلوحة مضيئة، تحملك لعالم من التأمل والسكون. \r\n\r\nبعد زيارتك للمسجد، لا تنسَ استكشاف ما حوله. تجد محلات تقليدية تقدم مأكولات محلية شهية، وتجربة المدينة الأصيلة بانتظارك. هنا، حيث يلتقي الماضي بالحاضر، تصبح الزيارة أكثر من مجرد رحلة، بل ذكرى خالدة تنبض بروحانية فريدة.', 'quba.jpg', ''),
(19, 3, 'Mount Uhud', 'جبل أحد', 'Mount Uhud: A Symbol of History and Beauty in Medina**  \r\n\r\nIf you\'re looking for an experience that combines the fragrance of history with the beauty of nature, **Mount Uhud** is your perfect destination when visiting Medina. This majestic mountain, stretching over 7 kilometers and rising to 1,077 meters, is not just a geological formation but a window into one of the greatest eras in Islamic history.  \r\n\r\nMount Uhud holds immense significance, as it was the site of the famous *Battle of Uhud*, one of the pivotal confrontations between the Muslims and the Quraysh. Nearby, you can visit the **Martyrs\' Cemetery**, which honors the companions who sacrificed their lives for Islam, including the beloved Hamza bin Abdul Muttalib, known as the \"Leader of Martyrs.\"  \r\n\r\nWhat makes Mount Uhud truly special is not just its rich history but also its captivating natural beauty. The mountain offers a unique landscape with towering peaks and the vibrant hues of its rocks, which become even more mesmerizing at sunrise and sunset. For photography enthusiasts, Mount Uhud provides panoramic views that are unforgettable.  \r\n\r\nNo visit is complete without stopping by the nearby traditional market, where you can purchase souvenirs and local gifts such as perfumes and Medina’s famous dates.  \r\n\r\nMount Uhud is more than just a mountain; it’s an experience that enriches your soul and connects you to a historical journey in one of the holiest places on earth.', 'جبل أحد: رمز التاريخ والجمال في المدينة المنورة\r\n\r\nإذا كنت تبحث عن تجربة تجمع بين عبق التاريخ وجمال الطبيعة، فإن جبل أحد هو وجهتك المثالية عند زيارة المدينة المنورة. هذا الجبل العظيم، الذي يمتد بطول 7 كيلومترات ويرتفع 1077 مترًا، ليس مجرد تشكيل جيولوجي بل نافذة على حقبة من أعظم الحقب في تاريخ الإسلام.\r\n\r\nيمثل جبل أحد موقعًا بالغ الأهمية، فقد كان شاهدًا على غزوة أحد الشهيرة، حيث دارت إحدى أعظم المعارك بين المسلمين وقريش. إلى جانب أهميته التاريخية، يُمكنك زيارة مقبرة الشهداء القريبة، التي تحتضن قبور الصحابة الذين ضحوا بأنفسهم من أجل نصرة الإسلام، وأبرزهم سيد الشهداء حمزة بن عبد المطلب رضي الله عنه.\r\n\r\nلكن ما يميز جبل أحد ليس فقط تاريخه العريق، بل أيضًا طبيعته الساحرة. الجبل يُعد معلمًا طبيعيًا فريدًا بقممه الشاهقة وألوان صخوره التي تأسر الأنظار عند شروق الشمس وغروبها. لمحبي التصوير الفوتوغرافي، يُوفر جبل أحد مناظر بانورامية رائعة تُخلد في الذاكرة.\r\n\r\nولن تكتمل زيارتك إلا بالتوقف عند السوق الشعبي المجاور، حيث يُمكنك شراء التذكارات والهدايا التقليدية مثل العطور والتمور المدينية الشهيرة.\r\n\r\nجبل أحد ليس مجرد جبل؛ إنه تجربة تُثري روحك، وتجعلك جزءًا من رحلة تاريخية لا تُنسى في أقدس بقاع الأرض.', 'uhad.jpeg', ''),
(21, 3, ' Miqat Mosque ', 'مسجد الميقات', 'The Miqat Mosque in Dhul-Hulayfah is an important destination for tourists interested in exploring the history of Medina. Located 9 kilometers from the Prophet\'s Mosque, it is a significant site where pilgrims begin their spiritual journey. The mosque features beautiful architecture and modern facilities, providing visitors with a peaceful place to relax and reflect before heading to Mecca. Tourists can also enjoy the spiritual atmosphere and learn about the historical significance of this site.', '\r\nمسجد الميقات في ذي الحليفة هو وجهة هامة للسياح الراغبين في استكشاف تاريخ المدينة المنورة. يقع على بعد 9 كيلومترات من المسجد النبوي، ويعد مكانًا مميزًا حيث يبدأ الحجاج والمعتمرون رحلتهم الروحية. يتميز المسجد بتصميمه الجميل والمرافق الحديثة، ويمنح الزوار فرصة لChatGPTلاسترخاء والتأمل قبل التوجه إلى مكة. يمكن للسياح أيضًا الاستمتاع بالأجواء الروحانية والتعرف على أهمية هذا المكان التاريخي.', 'megat.webp', ''),
(22, 3, 'Prophet\'s Mosque', 'المسجد النبوي الشريف', 'The Prophet\'s Mosque in Medina is the second holiest mosque in Islam after the Grand Mosque in Mecca. It was founded by the Prophet Muhammad ﷺ and contains his grave and the graves of Abu Bakr and Umar. The mosque is beautifully designed and includes the Rawdah Sharif, one of the best places for prayer and worship. Visiting the Prophet\'s Mosque provides a profound spiritual experience at one of Islam\'s holiest sites.', 'المسجد النبوي في المدينة المنورة هو ثاني أقدس مسجد في الإسلام بعد المسجد الحرام في مكة. تأسس على يد النبي محمد ﷺ ويحتوي على قبره وقبري \"أبو بكر الصديق\" و\"عمر بن الخطاب\" رضي الله عنهما. يتميز المسجد بتصميمه الرائع ويضم الروضة الشريفة، وهي من أفضل الأماكن للدعاء والعبادة. زيارة المسجد النبوي توفر تجربة روحية عميقة في أحد أقدس المواقع الإسلامية.', 'alsgd alnboy.jpg', ''),
(23, 3, 'Ali ibn Abi Talib Mosque', 'مسجد علي بن أبي طالب', 'Ali ibn Abi Talib Mosque in Medina is one of the significant historical and religious sites associated with the fourth caliph, Ali ibn Abi Talib (may Allah be pleased with him). It is said that the mosque was built on the spot where Ali prayed during his stay in Medina, giving it a special place in the hearts of Muslims.  \r\n\r\nThe mosque is distinguished by its simple design, reflecting the ascetic spirit for which Ali (may Allah be pleased with him) was known, making a visit there a uniquely spiritual experience. Located near many other Islamic landmarks in Medina, it serves as an essential destination for tourists and visitors seeking to explore the rich Islamic heritage.  \r\n\r\nA visit to the Ali ibn Abi Talib Mosque offers a chance to reflect on the life of one of Islam\'s greatest figures and is an unmissable stop on a religious tourism journey in Medina.', '**مسجد علي بن أبي طالب** في المدينة المنورة هو أحد المواقع التاريخية والدينية المهمة التي يرتبط اسمها بالخليفة الرابع علي بن أبي طالب رضي الله عنه. يُقال إن المسجد بُني في الموقع الذي صلى فيه علي أثناء إقامته في المدينة، مما يضفي عليه مكانة خاصة في قلوب المسلمين.  \r\n\r\nيتميز المسجد بتصميمه البسيط الذي يعكس روح الزهد التي عُرف بها علي رضي الله عنه، وهو ما يجعل زيارته تجربة روحانية مميزة. يقع المسجد في منطقة قريبة من العديد من المعالم الإسلامية الأخرى في المدينة المنورة، مما يجعله وجهة مهمة للسياح والزوار الراغبين في استكشاف التراث الإسلامي العريق.  \r\n\r\nزيارة مسجد علي بن أبي طالب تمنح فرصة للتأمل في حياة أحد أعظم الشخصيات الإسلامية، وتُعد محطة لا غنى عنها أثناء رحلة السياحة الدينية في المدينة المنورة.', 'ali.jpg', ''),
(24, 10, ' Lawrence of Arabia\'s House', 'منزل لورانس العرب', 'Lawrence of Arabia\'s House: A Journey to the Past in the Heart of Yanbu\r\n\r\nDiscover history at Lawrence of Arabia\'s house, where Thomas Edward Lawrence stayed during the Great Arab Revolt. The house stands as a testament to an important historical moment and reflects the authentic Hijazi architectural design.\r\n\r\nLocated in the heart of the old town, the house is surrounded by heritage alleys and traditional buildings, making it an ideal destination for history and culture enthusiasts. It offers an unforgettable experience that takes you on a journey to the past, filled with inspiring stories.', 'منزل لورانس العرب: رحلة إلى الماضي في قلب ينبع\r\n\r\nاكتشف التاريخ في منزل لورانس العرب، حيث أقام توماس إدوارد لورانس خلال فترة الثورة العربية الكبرى. يُعد المنزل شاهدًا على لحظة تاريخية مهمة، ويعكس تصميمه العمارة الحجازية الأصيلة.\r\n\r\nيقع المنزل في قلب البلدة القديمة، محاطًا بالأزقة التراثية والمباني التقليدية، مما يجعله وجهة مثالية لعشاق التاريخ والثقافة. تجربة لا تُنسى تأخذك في رحلة إلى الماضي المليء بالقصص الملهمة', 'LORANS.jpeg', ''),
(25, 10, 'Radwa Heritage Museum', 'متحف رضوى التراثي', 'Radwa Heritage Museum\r\n\r\nRadwa Heritage Museum is a unique cultural destination that celebrates Arab heritage, offering a rich experience that reflects the depth of local culture. The museum features a diverse collection of traditional tools, heritage clothing, and folk arts that showcase the history of the region.\r\n\r\nVisitors can enjoy guided tours and interactive workshops, making the visit an unforgettable experience. Radwa Museum is the perfect place for history and culture enthusiasts to dive deep into heritage and discover inspiring stories.', 'متحف رضوى التراثي\r\n\r\nمتحف رضوى التراثي هو وجهة ثقافية فريدة تحتفي بالتراث العربي، حيث يقدم تجربة غنية تعكس عراقة الثقافة المحلية. يحتوي المتحف على مجموعة متنوعة من الأدوات التقليدية والملابس التراثية، بالإضافة إلى الفنون الشعبية التي تعكس تاريخ المنطقة.\r\n\r\nيمكن للزوار الاستمتاع بجولات إرشادية وورش عمل تفاعلية، مما يجعل الزيارة تجربة لا تُنسى. إن متحف رضوى هو المكان المثالي لعشاق التاريخ والثقافة، حيث يمكنهم الغوص في عمق التراث واكتشاف القصص الملهمة.', 'radhwa-museum-in-.jpg', ''),
(26, 10, 'Yanbu Historical', 'ينبع التاريخية', 'Yanbu Historical is considered one of the oldest cities in the Kingdom of Saudi Arabia, with a long history that dates back to ancient times. Located on the coast of the Red Sea, it was an important commercial center in the past and served as a major stop for trade caravans. Yanbu Historical is characterized by its rich cultural and architectural heritage, featuring many traditional houses and old markets. It is also known for its festivals and cultural events that reflect local customs and traditions. Yanbu Historical is an ideal destination for visitors looking to explore the authentic history and heritage of Saudi Arabia.', 'ينبع التاريخية تعد واحدة من أقدم المدن في المملكة العربية السعودية، حيث تتمتع بتاريخ طويل يعود إلى العصور القديمة. تقع على ساحل البحر الأحمر، وقد كانت مركزًا تجاريًا هامًا في الماضي، حيث كانت محطة رئيسية للقوافل التجارية. تتميز ينبع التاريخية بتراثها الثقافي والمعماري الغني، حيث تحتوي على العديد من المنازل التقليدية والأسواق القديمة. كما تشتهر بمهرجاناتها وفعالياتها الثقافية التي تعكس العادات والتقاليد المحلية. تعتبر ينبع التاريخية وجهة مثالية للزوار الذين يرغبون في استكشاف التاريخ والتراث السعودي الأصيل.', 'HSYUN.jpg', ''),
(28, 10, 'Corniche', 'الكورنيش', 'The Yanbu Corniche is a charming destination overlooking the Red Sea, characterized by its serene atmosphere and breathtaking views. The corniche stretches along the coast, allowing visitors to enjoy delightful walks by the beach. You can relax under the sun or engage in exciting water activities. There are also many cafes and restaurants offering delicious seafood and traditional dishes. Families and friends can spend enjoyable times in the beautiful green spaces and gardens surrounding the corniche. Don’t miss the opportunity to visit the Yanbu Corniche and enjoy a unique experience that combines nature and entertainment!', 'كورنيش ينبع هو وجهة ساحرة تطل على البحر الأحمر حيث يتميز بأجوائه الهادئة والمناظر الخلابة يمتد الكورنيش على طول الساحل ليتيح للزوار الاستمتاع بنزهات رائعة على شاطئ البحر يمكنكم الاسترخاء تحت أشعة الشمس أو ممارسة الأنشطة المائية المثيرة كما يتوفر العديد من المقاهي والمطاعم التي تقدم أشهى الأطباق البحرية والوجبات الشعبية يمكن للعائلات والأصدقاء قضاء أوقات ممتعة في المساحات الخضراء والحدائق الجميلة التي تحيط بالكورنيش لا تفوتوا فرصة زيارة كورنيش ينبع واستمتعوا بتجربة فريدة تجمع بين الطبيعة والترفيه', 'CORNESH.jpg', ''),
(29, 10, 'Night Market', 'سوق الليل', 'The Night Market in Yanbu is a charming destination that combines authenticity and modernity, where visitors can enjoy a unique atmosphere under the stars. The market is adorned with various stalls offering delicious traditional foods and sweets. Visitors can also explore handmade crafts and local souvenirs that reflect the culture of the region. The ambiance is filled with joy and fun, making it an ideal place for families and friends to spend enjoyable moments and experience unforgettable shopping in a magical setting. Don’t miss the chance to visit the Night Market in Yanbu and enjoy every moment you spend there!', 'سوق الليل في ينبع هو وجهة ساحرة تجمع بين الأصالة والحداثة حيث يمكن للزوار الاستمتاع بأجواء فريدة من نوعها تحت ضوء النجوم يتزين السوق بأكشاك متنوعة تقدم أشهى المأكولات الشعبية والحلويات التقليدية كما يمكن للزوار استكشاف الحرف اليدوية والتذكارات المحلية التي تعكس ثقافة المنطقة تتميز الأجواء بالبهجة والمرح مما يجعله مكانا مثاليا للعائلات والأصدقاء لقضاء أوقات ممتعة وتجربة تسوق لا تنسى في أجواء ساحرة لا تفوتوا فرصة زيارة سوق الليل في ينبع واستمتعوا بكل لحظة فيه', 'SOG.jpg', ''),
(30, 1, 'Souk Okaz', 'سوق عكاظ', 'Souk Okaz is one of the most prominent cultural and historical landmarks in the Kingdom of Saudi Arabia. It features an atmosphere of familiarity and heritage that attracts visitors from all over the world. Tourists can explore traditional arts and diverse crafts, and enjoy theatrical and poetic performances that reflect the history and culture of the Arabs. The market is distinguished by its charming location amidst breathtaking nature, offering visitors a unique experience that combines history and natural beauty. Don’t miss the opportunity to taste traditional foods and learn about the authentic customs and traditions that embody the identity of the region. Souk Okaz is the perfect destination for anyone seeking a rich and enjoyable experience at the heart of Arab culture.', 'سوق عكاظ هو واحد من أبرز المعالم الثقافية والتاريخية في المملكة العربية السعودية يتميز بجو من الألفة والتراث يجذب الزوار من جميع أنحاء العالم يمكن للسياح استكشاف الفنون التقليدية والحرف اليدوية المتنوعة كما يمكنهم الاستمتاع بالعروض المسرحية والشعرية التي تعكس تاريخ العرب وثقافتهم يمتاز السوق بموقعه الساحر وسط الطبيعة الخلابة مما يتيح للزوار تجربة فريدة من نوعها تجمع بين التاريخ والجمال الطبيعي لا تفوتوا الفرصة لتذوق الأطعمة الشعبية والتعرف على العادات والتقاليد الأصيلة التي تعكس هوية المنطقة سوق عكاظ وجهة مثالية لكل من يبحث عن تجربة غنية وممتعة في قلب الثقافة العربية', 'AKAS.jpg', '1'),
(31, 1, 'Al-Sharif Museum', 'متحف الشريف', 'Al-Sharif Museum\r\n\r\nAl-Sharif Museum is an important cultural destination that reflects the rich heritage and history of the Kingdom. The museum features diverse collections, including traditional tools, heritage clothing, and folk arts, providing visitors with a unique and enjoyable experience.\r\n\r\nVisitors can explore exhibits that tell stories about daily life and local culture, as well as participate in workshops and cultural events. Al-Sharif Museum is an ideal place for history and culture enthusiasts to learn about the region\'s rich heritage and ancient history.', 'متحف الشريف\r\n\r\nمتحف الشريف هو وجهة ثقافية مهمة تعكس التراث والتاريخ الغني للمملكة. يتميز المتحف بمجموعاته المتنوعة التي تشمل الأدوات التقليدية، الملابس التراثية، والفنون الشعبية، مما يوفر للزوار تجربة فريدة وممتعة.\r\n\r\nيمكن للزوار استكشاف المعروضات التي تحكي قصصًا عن الحياة اليومية والثقافة المحلية، بالإضافة إلى المشاركة في ورش العمل والفعاليات الثقافية. يعد متحف الشريف مكانًا مثاليًا لعشاق التاريخ والثقافة، حيث يمكنهم التعرف على التراث الغني والتاريخ العريق للمنطقة.', 'MTHF.jpg', ''),
(32, 9, 'Clock Tower', 'برج الساعة', 'The Clock Tower in Mecca is one of the most prominent tourist attractions in the Islamic world. This tower embodies luxury and modernity and is among the tallest towers in the world. It boasts a stunning view of the Holy Kaaba and the surrounding areas. The tower features various facilities, including hotels, shopping centers, and restaurants offering delicious cuisine. Visitors can enjoy watching the giant clock that illuminates the sky at night, as well as the viewing platforms that provide breathtaking panoramic views of the city and the holy sites. The Clock Tower is a symbol of the cultural development in Mecca and reflects the unique architectural spirit that characterizes the city. It represents a meeting point between history and modernity, making it a must-visit destination for anyone traveling to Mecca.', 'برج الساعة بمكة هو واحد من أبرز المعالم السياحية في العالم الإسلامي يجسد هذا البرج الفخامة والحداثة ويعد من أعلى الأبراج في العالم يتمتع بإطلالة رائعة على الكعبة المشرفة والمناطق المحيطة بها يضم البرج مرافق متنوعة مثل الفنادق والمراكز التجارية والمطاعم التي تقدم أشهى المأكولات يمكن للزوار الاستمتاع بمشاهدة الساعة العملاقة التي تضيء السماء ليلاً إضافة إلى إمكانية زيارة منصات المشاهدة التي توفر مناظر بانورامية مذهلة للمدينة والمشاعر المقدسة يعد برج الساعة رمزاً للتطور الحضاري في مكة ويعكس الروح المعمارية الفريدة التي تميز المدينة كما يمثل نقطة التقاء بين التاريخ والحداثة مما يجعله وجهة لا بد من زيارتها لكل من يزور مكة المكرمة', 'BRG.jpg', '1'),
(33, 9, 'Al-Masjid Al-Haram', 'المسجد الحرام', 'The Grand Mosque, or Al-Masjid Al-Haram, is the holiest place in Islam and a major attraction for Muslims from all over the world. It is distinguished by its beauty and spirituality, as it houses the Kaaba, the qibla for Muslims in their prayers. The Grand Mosque holds special significance during the seasons of Hajj and Umrah, as millions gather to perform their rituals in an atmosphere filled with devotion and tranquility. Visitors can enjoy a tour around the Kaaba and perform the Tawaf. They can also explore the historical areas surrounding the mosque, such as the Grand Mosque library and traditional markets that offer handmade crafts and souvenirs. The Grand Mosque is not just a place for prayer; it is a unique spiritual experience where worship blends with serenity and peace, making it an unforgettable destination for every visitor.', 'المسجد الحرام هو أقدس مكان في الإسلام ومركز جذب المسلمين من جميع أنحاء العالم يتميز بجماله وروحانيته حيث يحتضن الكعبة المشرفة التي تعتبر قبلة المسلمين في صلواتهم يكتسب المسجد الحرام أهمية خاصة خلال مواسم الحج والعمرة حيث يتوافد الملايين لأداء مناسكهم في أجواء مليئة بالخشوع والسكينة يمكنك الاستمتاع بجولة حول الكعبة والطواف بها كما يمكنك زيارة المناطق التاريخية المحيطة بالمسجد مثل مكتبة الحرم الشريف والأسواق التقليدية التي تقدم مشغولات يدوية وهدايا تذكارية المسجد الحرام ليس مجرد مكان للصلاة بل هو تجربة روحانية فريدة تمتزج فيها العبادة بالسكينة والطمأنينة مما يجعله وجهة لا تنسى لكل زائر', 'HRM M.jpg', ''),
(34, 9, 'Cultural Area of Hira', 'منطقة حراء الثقافية', 'Welcome to the Cultural Area of Hira, where heritage meets creativity in a unique experience. Enjoy the beauty of nature with the stunning landscapes that surround this historically rich area. Explore the cultural and artistic landmarks that reflect the authentic Saudi identity, and discover traditional arts and crafts through interactive workshops. Don\'t miss the chance to visit this wonderful area and experience a memorable journey that combines learning and entertainment in an atmosphere full of vitality and inspiration.', 'منطقة حراء الثقافية حيث يلتقي التراث مع الإبداع في تجربة فريدة من نوعها استمتعوا بجمال الطبيعة مع المناظر الخلابة التي تحيط بهذه المنطقة الغنية بالتاريخ استكشفوا المعالم الثقافية والفنية التي تعكس الهوية السعودية الأصيلة وتعرفوا على الفنون والحرف التقليدية من خلال ورش عمل تفاعلية لا تفوتوا فرصة زيارة هذه المنطقة الرائعة وعيشوا تجربة مميزة تجمع بين التعلم والترفيه في أجواء مليئة بالحيوية والإلهام', 'HRAA.jpg', '');

