CREATE TABLE `regions` (
  `Id` int(11) NOT NULL,
  `Name` varchar(100) NOT NULL,
  `Name_ar` varchar(100) DEFAULT NULL,
  `Description` text DEFAULT NULL,
  `Description_ar` varchar(10000) DEFAULT NULL,
  `Path` mediumtext NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `regions`
--

INSERT INTO `regions` (`Id`, `Name`, `Name_ar`, `Description`, `Description_ar`, `Path`) VALUES
(1, 'Taif', 'الطائف', 'taif, often called the \"City of Roses,\" is a picturesque destination in the Sarawat Mountains of Saudi Arabia. Known for its cooler climate, it serves as a summer retreat for those looking to escape the heat of the surrounding regions. The city\'s landscapes are adorned with lush gardens and rose fields that produce some of the finest rose water and perfumes in the world, celebrated annually during the renowned Rose Festival.', 'الطائف، التي يطلق عليها غالبًا \"مدينة الورود\"، هي وجهة خلابة في جبال السروات في المملكة العربية السعودية. تشتهر بمناخها البارد، وهي بمثابة ملاذ صيفي لأولئك الذين يتطلعون إلى الهروب من حرارة المناطق المحيطة. تزين المناظر الطبيعية في المدينة الحدائق المورقة وحقول الورد التي تنتج بعضًا من أجود مياه الورد والعطور في العالم، والتي يتم الاحتفال بها سنويًا خلال مهرجان الورد الشهير.', 'ti.jpg'),
(2, 'Jeddah', 'جدة', 'Jeddah, the Bride of the Red Sea, beautifully blends heritage and modernity. Explore its historic neighborhoods like Al-Balad and enjoy its stunning Corniche with breathtaking views of the Red Sea. Discover its unique restaurants and markets, and don’t miss King Fahd’s Fountain, the tallest in the world. Jeddah is a vibrant and unforgettable destination', 'جدة، عروس البحر الأحمر، تمزج بشكل جميل بين التراث والحداثة. استكشف أحيائها التاريخية مثل البلد واستمتع بكورنيشها المذهل بإطلالات خلابة على البحر الأحمر. اكتشف مطاعمها وأسواقها الفريدة، ولا تفوت نافورة الملك فهد، الأطول في العالم. جدة هي وجهة نابضة بالحياة ولا تُنسى', 'JEddah.jpg'),
(3, 'Medina', 'المدينة المنورة', 'Medina, Al-Tayyiba, is the city of peace and serenity. It is home to the Prophet’s Mosque and Quba Mosque, with historic landmarks like Mount Uhud and traditional markets. With its spiritual atmosphere and rich heritage, Medina offers a unique experience that blends faith and history', 'المدينة المنورة، الطيبة، هي مدينة السلام والسكينة، فهي موطن المسجد النبوي ومسجد قباء، ومعالم تاريخية مثل جبل أحد والأسواق التقليدية. بأجوائها الروحانية وتراثها الغني، تقدم المدينة المنورة تجربة فريدة تجمع بين الإيمان والتاريخ', 'Medina.jpg'),
(8, 'Al-Ula', 'العلا', 'Discover AlUla: A Timeless Journey Through History and Nature\r\n\r\nStep into AlUla, Saudi Arabia’s hidden gem, where ancient history meets breathtaking landscapes. Home to UNESCO World Heritage sites like Hegra, AlUla offers a mesmerizing blend of rich culture, stunning rock formations, and endless desert beauty. Wander through lush oases, marvel at ancient inscriptions, and experience the magic of starlit desert skies.\r\n\r\nWhether you seek adventure, tranquility, or a glimpse into civilizations past, AlUla promises a one-of-a-kind journey that will captivate your senses and leave you yearning for more. Come explore the soul of Arabia, where every moment tells a story', 'اكتشف العلا: رحلة خالدة عبر التاريخ والطبيعة\r\n\r\nادخل إلى العلا، جوهرة المملكة العربية السعودية المخفية، حيث يلتقي التاريخ القديم بالمناظر الطبيعية الخلابة. تعد العلا موطنًا لمواقع التراث العالمي لليونسكو مثل الحجر، وتوفر مزيجًا ساحرًا من الثقافة الغنية والتكوينات الصخرية المذهلة وجمال الصحراء اللامتناهي. تجول عبر الواحات الخصبة، وانبهر بالنقوش القديمة، وجرب سحر سماء الصحراء المرصعة بالنجوم.\r\n\r\nسواء كنت تبحث عن المغامرة أو الهدوء أو لمحة عن الحضارات الماضية، فإن العلا تعدك برحلة فريدة من نوعها ستأسر حواسك وتجعلك تتوق إلى المزيد. تعال واستكشف روح الجزيرة العربية، حيث تحكي كل لحظة قصة', 'AL.jpg'),
(9, 'Makkah', 'مكة', 'Makkah Al-Mukarramah, the cradle of Islam and the holiest place on earth, is a unique spiritual destination that combines authenticity with modernity. It is home to the Grand Mosque and the Kaaba, attracting millions annually for Hajj and Umrah. Additionally, Makkah offers visitors a distinctive experience through its historical landmarks and traditional markets. It is not just a place of worship but an extraordinary journey that fills the soul with tranquility and peace.', 'مكة المكرمة، مهد الإسلام وأقدس مكان على وجه الأرض، وجهة روحانية فريدة تجمع بين الأصالة والحداثة، فهي موطن المسجد الحرام والكعبة المشرفة، وتجذب الملايين سنويًا للحج والعمرة، بالإضافة إلى ذلك، تقدم مكة المكرمة لزوارها تجربة مميزة من خلال معالمها التاريخية وأسواقها التقليدية، فهي ليست مجرد مكان للعبادة بل رحلة غير عادية تملأ النفس بالهدوء والسلام.', 'M.jpg'),
(10, 'Yanbu', 'ينبع', 'Yanbu, a coastal gem on the Red Sea, offers a perfect blend of stunning natural beauty and exciting marine activities. It is renowned for its soft sandy beaches and crystal-clear waters, making it an ideal destination for diving enthusiasts and coral reef exploration. Moreover, Yanbu embraces a rich cultural heritage and traditional markets that add an authentic touch to any visit. It’s the perfect spot for those seeking both relaxation and adventure.', 'تقدم ينبع، جوهرة ساحلية على البحر الأحمر، مزيجًا مثاليًا من الجمال الطبيعي المذهل والأنشطة البحرية المثيرة. تشتهر بشواطئها الرملية الناعمة ومياهها الصافية، مما يجعلها وجهة مثالية لعشاق الغوص واستكشاف الشعاب المرجانية. علاوة على ذلك، تحتضن ينبع تراثًا ثقافيًا غنيًا وأسواقًا تقليدية تضيف لمسة أصيلة إلى أي زيارة. إنها المكان المثالي لأولئك الذين يبحثون عن الاسترخاء والمغامرة.', 'yan.jpg');

